select
  'month' as grain,
  cast(metric_time__month as date) as period_start,
  'total' as slice,
  cast(null as string) as slice_value,
  bookings_mtd,
  bookings_wow_growth
from (
  -- Combine Aggregated Outputs
  -- Write to DataTable
  WITH sma_10004_cte AS (
    -- Read Elements From Semantic Model 'bookings'
    -- Metric Time Dimension 'booked_date'
    SELECT
      TIMESTAMP_TRUNC(booked_date, day) AS metric_time__day
      , TIMESTAMP_TRUNC(booked_date, month) AS metric_time__month
      , 1 AS __bookings
    FROM {{ ref('slv_bookings') }} bookings_src_10000
  )

  SELECT
    COALESCE(subq_11.metric_time__month, subq_28.metric_time__month) AS metric_time__month
    , MAX(subq_11.bookings_mtd) AS bookings_mtd
    , MAX(subq_28.bookings_wow_growth) AS bookings_wow_growth
  FROM (
    -- Re-aggregate Metric via Group By
    SELECT
      metric_time__month
      , bookings_mtd
    FROM (
      -- Window Function for Metric Re-aggregation
      SELECT
        metric_time__month
        , LAST_VALUE(bookings_mtd) OVER (
          PARTITION BY metric_time__month
          ORDER BY metric_time__day
          ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
        ) AS bookings_mtd
      FROM (
        -- Join Self Over Time Range
        -- Select: ['__bookings', 'metric_time__month', 'metric_time__day']
        -- Select: ['__bookings', 'metric_time__month', 'metric_time__day']
        -- Aggregate Inputs for Simple Metrics
        -- Compute Metrics via Expressions
        -- Compute Metrics via Expressions
        SELECT
          subq_3.date_day AS metric_time__day
          , TIMESTAMP_TRUNC(subq_3.date_day, month) AS metric_time__month
          , SUM(sma_10004_cte.__bookings) AS bookings_mtd
        FROM {{ ref('metricflow_time_spine') }} subq_3
        INNER JOIN
          sma_10004_cte
        ON
          (
            sma_10004_cte.metric_time__day <= subq_3.date_day
          ) AND (
            sma_10004_cte.metric_time__day >= TIMESTAMP_TRUNC(subq_3.date_day, month)
          )
        GROUP BY
          metric_time__day
          , metric_time__month
      ) subq_9
    ) subq_10
    GROUP BY
      metric_time__month
      , bookings_mtd
  ) subq_11
  FULL OUTER JOIN (
    -- Compute Metrics via Expressions
    SELECT
      metric_time__month
      , (bookings - bookings_prior_week) * 1.0 / nullif(bookings_prior_week, 0) AS bookings_wow_growth
    FROM (
      -- Combine Aggregated Outputs
      SELECT
        COALESCE(subq_16.metric_time__month, subq_26.metric_time__month) AS metric_time__month
        , MAX(subq_16.bookings) AS bookings
        , MAX(subq_26.bookings_prior_week) AS bookings_prior_week
      FROM (
        -- Read From CTE For node_id=sma_10004
        -- Select: ['__bookings', 'metric_time__month']
        -- Select: ['__bookings', 'metric_time__month']
        -- Aggregate Inputs for Simple Metrics
        -- Compute Metrics via Expressions
        SELECT
          metric_time__month
          , SUM(__bookings) AS bookings
        FROM sma_10004_cte
        GROUP BY
          metric_time__month
      ) subq_16
      FULL OUTER JOIN (
        -- Join to Time Spine Dataset
        -- Select: ['__bookings', 'metric_time__month']
        -- Select: ['__bookings', 'metric_time__month']
        -- Aggregate Inputs for Simple Metrics
        -- Compute Metrics via Expressions
        SELECT
          TIMESTAMP_TRUNC(time_spine_src_10000.date_day, month) AS metric_time__month
          , SUM(sma_10004_cte.__bookings) AS bookings_prior_week
        FROM {{ ref('metricflow_time_spine') }} time_spine_src_10000
        INNER JOIN
          sma_10004_cte
        ON
          DATE_SUB(CAST(time_spine_src_10000.date_day AS DATETIME), INTERVAL 1 week) = sma_10004_cte.metric_time__day
        GROUP BY
          metric_time__month
      ) subq_26
      ON
        subq_16.metric_time__month = subq_26.metric_time__month
      GROUP BY
        metric_time__month
    ) subq_27
  ) subq_28
  ON
    subq_11.metric_time__month = subq_28.metric_time__month
  GROUP BY
    metric_time__month
) as metricflow
